// UI Library — lookup page. Data lives in tool/data/*.json (generated by scripts/build_tool.py).
const R = "../"; // ui-library root (the page runs at /tool/)
const $ = (s, el = document) => el.querySelector(s);
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const norm = (s) => String(s ?? "").toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/đ/g, "d");
const cache = {};
const data = (n) => (cache[n] ??= fetch(`data/${n}.json`).then((r) => r.json()));
const text = (p) => fetch(R + p).then((r) => { if (!r.ok) throw new Error(r.status); return r.text(); });
const view = $("#view");

function toast(msg) { const t = $("#toast"); t.textContent = msg; t.classList.add("show"); clearTimeout(t._h); t._h = setTimeout(() => t.classList.remove("show"), 1600); }
async function copy(s, msg = "Copied") { await navigator.clipboard.writeText(s); toast(msg); }
function modal(title, html, actions = []) {
  $("#modal-title").textContent = title;
  $("#modal-body").innerHTML = html;
  const box = $("#modal-actions"); box.innerHTML = "";
  for (const [label, fn] of actions) { const b = document.createElement("button"); b.className = "btn"; b.textContent = label; b.onclick = fn; box.append(b); }
  $("#modal").showModal();
}
$("#modal-close").onclick = () => $("#modal").close();
async function showMd(path) {
  try { modal(path.split("/").slice(-2).join("/"), `<div class="md">${marked.parse(await text(path))}</div>`, [["Open folder", () => open(R + path.replace(/[^/]+$/, ""))]]); }
  catch { toast("Could not open " + path); }
}
async function showCode(title, path, extra = []) {
  modal(title, `<pre>Loading…</pre>`);
  try {
    const code = await text(path);
    $("#modal-body").innerHTML = `<p class="meta">${esc(path)}</p><pre>${esc(code)}</pre>`;
    $("#modal-actions").innerHTML = "";
    for (const [label, fn] of [["Copy code", () => copy(code)], ["Copy path", () => copy(path)], ...extra]) {
      const b = document.createElement("button"); b.className = "btn"; b.textContent = label; b.onclick = fn; $("#modal-actions").append(b);
    }
  } catch { $("#modal-body").innerHTML = `<p>Could not read file ${esc(path)}</p>`; }
}

// List with search + filters + "show more" paging
function listPage({ intro, filters = [], items, match, render, wrapClass, pageSize = 120 }) {
  view.innerHTML = `${intro ? `<div class="intro">${intro}</div>` : ""}
    <div class="bar"><input type="search" placeholder="Search (Vietnamese without accents works too)…" id="q">${filters.map((f) => f.html).join("")}<span class="count" id="cnt"></span></div>
    <div class="${wrapClass}" id="out"></div><button class="btn more" id="more">Show more</button>`;
  let shown = 0, rows = [];
  const draw = (reset) => {
    if (reset) {
      const q = norm($("#q").value).split(/\s+/).filter(Boolean);
      const fv = filters.map((f) => $("#" + f.id).type === "checkbox" ? $("#" + f.id).checked : $("#" + f.id).value);
      rows = items.filter((x) => match(x, fv) && q.every((w) => (x._s ??= norm(x._search ?? JSON.stringify(x))).includes(w)));
      shown = 0; $("#out").innerHTML = "";
    }
    const start = shown, chunk = rows.slice(shown, shown + pageSize); shown += chunk.length;
    $("#out").insertAdjacentHTML("beforeend", chunk.map((x, k) => render(x, start + k)).join(""));
    $("#cnt").textContent = `${rows.length.toLocaleString("en")} results`;
    $("#more").style.display = shown < rows.length ? "" : "none";
  };
  $("#q").oninput = () => draw(true);
  filters.forEach((f) => ($("#" + f.id).onchange = () => draw(true)));
  $("#more").onclick = () => draw(false);
  $("#out").onclick = (e) => { const el = e.target.closest("[data-i]"); if (el) open_(rows[+el.dataset.i], e); };
  let open_ = () => {};
  const api = { onOpen: (fn) => (open_ = fn), rowsIndex: () => rows };
  draw(true);
  return api;
}
const sel = (id, label, opts) => ({ id, html: `<select id="${id}"><option value="">${label}</option>${opts.map((o) => `<option>${esc(o)}</option>`).join("")}</select>` });
const chk = (id, label) => ({ id, html: `<label><input type="checkbox" id="${id}"> ${label}</label>` });
const fam = (x) => "kgd-" + norm(x.src + x.name).replace(/[^a-z0-9]/g, "");
const uniq = (a) => [...new Set(a.filter(Boolean))].sort();

const TABS = {
  async "Catalog"() {
    const cat = await data("catalog");
    const st = { downloaded: "Downloaded", partial: "Partly downloaded", "link-only": "Link only" };
    const all = cat.flatMap((g) => g.sites);
    const n = (k) => all.filter((s) => s.status === k).length;
    view.innerHTML = `<div class="intro">75 websites in ${cat.length} groups. <b>${n("downloaded")}</b> fully downloaded, <b>${n("partial")}</b> partly downloaded, <b>${n("link-only")}</b> link only (needs a login, is an online tool, or the license does not allow bulk downloads). Click “Guide” to see how to use each source.</div>` +
      cat.map((g) => `<section class="group"><h2>${esc(g.title)}</h2><div class="cards">${g.sites.map((s) => `
        <div class="card"><h3>${esc(new URL(s.url).hostname.replace("www.", ""))}</h3>
        <div><span class="badge b-${s.status}">${st[s.status] || s.status}</span> ${s.license ? `<span class="meta">· ${esc(s.license)}</span>` : ""} ${s.size ? `<span class="meta">· ${esc(s.size)}</span>` : ""}</div>
        <p>${esc(s.desc)}</p>${s.notes ? `<p><b>Collected:</b> ${esc(s.notes)}</p>` : ""}${s.usage ? `<p><b>How to use:</b> ${esc(s.usage)}</p>` : ""}
        <div class="row"><a class="btn" href="${esc(s.url)}" target="_blank" rel="noopener">Open site ↗</a>
        ${s.local_path ? `<a class="btn" href="${R + esc(s.local_path)}/" target="_blank">Folder</a>` : ""}
        ${s.readme ? `<button class="btn" data-md="${esc(s.readme)}">Guide</button>` : ""}</div></div>`).join("")}</div></section>`).join("");
    view.onclick = (e) => { const b = e.target.closest("[data-md]"); if (b) showMd(b.dataset.md); };
  },

  async "Components"() {
    const items = await data("components");
    const p = listPage({
      intro: "Source code for buttons, cards, page blocks and effects. Click an item to view and copy its code. <b>React</b>: copy the .tsx file into your project (usually <code>components/ui/</code>). <b>HTML</b>: daisyUI and Flowbite use Tailwind classes; see the examples in their docs.",
      filters: [sel("f-lib", "All libraries", uniq(items.map((x) => x.lib))), sel("f-cat", "All types", uniq(items.map((x) => x.cat))), sel("f-stack", "React + HTML", ["react", "html"])],
      items, wrapClass: "list",
      match: (x, [lib, cat, stack]) => (!lib || x.lib === lib) && (!cat || x.cat === cat) && (!stack || x.stack === stack),
      render: (x, i) => `<div class="item" data-i="${i}"><b>${esc(x.name)}</b><span class="meta">${esc(x.lib)}${x.cat ? " · " + esc(x.cat) : ""} · ${x.stack === "html" ? "HTML" : "React"}</span></div>`,
    });
    p.onOpen((x) => {
      const extra = [];
      if (x.demo) extra.push(["View demo", () => open(R + x.path)]);
      if (x.folder) extra.push(["Open folder", () => open(R + x.folder + "/")]);
      for (const [v, fs] of Object.entries(x.variants || {})) for (const f of fs) if (f !== x.path) extra.push([`${v}/${f.split("/").pop()}`, () => showCode(x.name, f)]);
      showCode(`${x.name} — ${x.lib} (${x.license || ""})`, x.path, extra);
    });
  },

  async "Prompt"() {
    const items = (await data("prompts")).map((x) => ({ ...x, src: x.site || new URL(x.url.split(" ")[0]).hostname, _search: `${x.title} ${x.category} ${(x.tags || []).join(" ")}` }));
    const p = listPage({
      intro: "Website templates with prompts from GetLayers, MotionSites and Aura. Most prompt text needs a login to copy, so click “Open site” and copy it from the original page. Items tagged <b>has prompt</b> are already saved here. See 20 more sample prompts in the Guides tab (PROMPT_EXAMPLES.md).",
      filters: [sel("f-src", "All sources", uniq(items.map((x) => x.src))), sel("f-tier", "All plans", uniq(items.map((x) => x.tier))), chk("f-has", "Only items with a prompt")],
      items, wrapClass: "cards",
      match: (x, [src, tier, has]) => (!src || x.src === src) && (!tier || x.tier === tier) && (!has || x.has_prompt_text),
      render: (x, i) => `<div class="card"><h3>${esc(x.title)}</h3><div><span class="badge ${/free/i.test(x.tier) ? "b-downloaded" : "b-link-only"}">${esc(x.tier)}</span> ${x.has_prompt_text ? '<span class="badge b-partial">has prompt</span>' : ""} <span class="meta">${esc(x.src)} · ${esc(x.category || "")}</span></div>
        <p>${esc((x.tags || []).join(", "))}</p><div class="row">${/^https?:/.test(x.url) ? `<a class="btn" href="${esc(x.url)}" target="_blank" rel="noopener">Open site ↗</a>` : ""}${x.file ? `<button class="btn" data-i="${i}">View prompt</button>` : ""}</div></div>`,
    });
    p.onOpen((x) => x.file && showMd("assets/prompt-templates/" + x.file));
  },

  async "Icon"() {
    const sets = await data("icons");
    const items = Object.entries(sets).flatMap(([k, s]) => s.items.map(([name, tags, files]) => ({ set: k, base: s.base, name, files, _search: name + " " + tags })));
    const weights = uniq(items.flatMap((x) => Object.keys(x.files)));
    const p = listPage({
      intro: "Lucide, Phosphor, Heroicons — search by name or English keyword (e.g. home, user, cart). Click an icon to <b>copy its SVG code</b> (paste it straight into HTML). In React, use the <code>lucide-react</code>, <code>@phosphor-icons/react</code> or <code>@heroicons/react</code> packages.",
      filters: [sel("f-set", "All icon sets", Object.keys(sets)), sel("f-w", "Default style", weights)],
      items, wrapClass: "grid-ic", pageSize: 300,
      match: (x, [set, w]) => (!set || x.set === set) && (!w || x.files[w]),
      render: (x, i) => { const w = $("#f-w")?.value; const f = x.files[w] || Object.values(x.files)[0];
        return `<div class="ic" data-i="${i}" title="${esc(x.set + ": " + x.name)}"><img class="mono" loading="lazy" src="${R + esc(x.base + f)}" alt=""><span>${esc(x.name)}</span></div>`; },
    });
    p.onOpen(async (x) => { const w = $("#f-w").value; const f = x.files[w] || Object.values(x.files)[0]; copy(await text(x.base + f), `Copied SVG “${x.name}” (${x.set})`); });
  },

  async "Font"() {
    const items = (await data("fonts")).map((x) => ({ ...x, _search: `${x.name} ${x.cat} ${x.src}` }));
    const loaded = new Set();
    const p = listPage({
      intro: "Free fonts downloaded to this computer. Tick “Vietnamese support” to show only fonts that include Vietnamese accents. Click “Copy CSS” to get the <code>@font-face</code> snippet. See font pairing suggestions in the Guides tab (font-pairings-vietnamese.md).",
      filters: [chk("f-vi", "Vietnamese support"), sel("f-src", "All sources", uniq(items.map((x) => x.src))), sel("f-cat", "All font styles", uniq(items.map((x) => x.cat)))],
      items, wrapClass: "cards", pageSize: 60,
      match: (x, [vi, src, cat]) => (!vi || x.vi) && (!src || x.src === src) && (!cat || x.cat === cat),
      render: (x, i) => `<div class="card font-card" data-font="${i}"><h3>${esc(x.name)}</h3><div class="meta">${esc(x.src)} · ${esc(x.cat || "")} · ${esc(x.license || "")} ${x.vi ? '<span class="badge b-downloaded">Vietnamese</span>' : ""}</div>
        <div class="sample" style="font-family:'${fam(x)}',serif">${x.vi ? "Phở bò Hà Nội — Đường đi khó" : "The quick brown fox 123"}</div>
        <div class="row"><button class="btn" data-i="${i}">Copy CSS</button>${x.files[0] ? `<a class="btn" href="${R + esc(x.files[0].replace(/[^/]+$/, ""))}" target="_blank">Folder</a>` : ""}</div></div>`,
    });
    const io = new IntersectionObserver((es) => es.forEach((e) => {
      if (!e.isIntersecting) return; const i = +e.target.dataset.font; const x = p.rowsIndex()[i];
      if (!x || loaded.has(x.name) || !x.files[0]) return; loaded.add(x.name);
      const f = x.files.find((f) => /regular|\[wght\]|-400|book/i.test(f)) || x.files[0];
      new FontFace(fam(x), `url("${R + encodeURI(f)}")`).load().then((ff) => document.fonts.add(ff)).catch(() => {});
    }));
    new MutationObserver(() => document.querySelectorAll("[data-font]:not([data-o])").forEach((el) => { el.dataset.o = 1; io.observe(el); })).observe($("#out"), { childList: true });
    document.querySelectorAll("[data-font]").forEach((el) => { el.dataset.o = 1; io.observe(el); });
    p.onOpen((x) => {
      const css = x.files.filter((f) => /\.(woff2?|ttf|otf)$/i.test(f)).map((f) => {
        const w = (f.match(/(\d00)/) || [, "400"])[1]; const it = /italic/i.test(f) ? "italic" : "normal"; const vf = /\[wght/.test(f);
        return `@font-face {\n  font-family: "${x.name}";\n  src: url("/fonts/${f.split("/").pop()}");\n  font-weight: ${vf ? "100 900" : w};\n  font-style: ${it};\n  font-display: swap;\n}`;
      }).join("\n") + `\n/* Copy the font files from: ${x.files[0]?.replace(/[^/]+$/, "")} into your project's public/fonts folder */\nbody { font-family: "${x.name}", system-ui, sans-serif; }`;
      copy(css, `Copied CSS for ${x.name}`);
    });
  },

  async "Colors & Themes"() {
    const c = await data("colors");
    const sw = (obj, keys) => `<div class="swatches">${keys.map((k) => obj[k] ? `<i style="background:${esc(obj[k])}" title="${k}: ${esc(obj[k])}"></i>` : "").join("")}</div>`;
    view.innerHTML = `<div class="intro">Color sets for shadcn/ui (42 themes from tweakcn) and self-made palettes that meet the AA contrast standard. Click “Copy CSS” and paste it into <code>globals.css</code> (React/Next.js) or a &lt;style&gt; tag (HTML).</div>
      <section class="group"><h2>Theme shadcn/ui (tweakcn)</h2><div class="cards">${c.tweakcn.map((t, i) => `<div class="card"><h3>${esc(t.label || t.slug)}</h3>
        ${sw(t.light || {}, ["background", "primary", "secondary", "accent", "foreground"])}${sw(t.dark || {}, ["background", "primary", "secondary", "accent", "foreground"])}
        <div class="row"><button class="btn" data-css="${esc(t.css)}">Copy CSS</button><button class="btn" data-view="${esc(t.css)}">View</button></div></div>`).join("")}</div></section>
      <section class="group"><h2>Self-made palettes</h2><div class="cards">${c.palettes.map((p) => `<div class="card"><h3>${esc(p.name || p.slug)}</h3>${sw(p.colors, Object.keys(p.colors))}
        <p>${Object.entries(p.colors).map(([k, v]) => `${k}: ${v}`).join(" · ")}</p><div class="row"><button class="btn" data-json='${esc(JSON.stringify(p.colors))}'>Copy color codes</button></div></div>`).join("")}</div></section>
      <section class="group"><h2>Type sizes & spacing</h2><div class="cards">${[...c.typescale, ...c.utopia].map((f) => `<div class="card"><h3>${esc(f.split("/").pop())}</h3><div class="row"><button class="btn" data-css="${esc(f)}">Copy CSS</button><button class="btn" data-view="${esc(f)}">View</button></div></div>`).join("")}</div></section>`;
    view.onclick = async (e) => {
      const b = e.target.closest("button"); if (!b) return;
      if (b.dataset.css) copy(await text(b.dataset.css));
      if (b.dataset.view) showCode(b.dataset.view.split("/").pop(), b.dataset.view);
      if (b.dataset.json) copy(JSON.stringify(JSON.parse(b.dataset.json), null, 2));
    };
  },

  async "Images"() {
    const items = (await data("images")).map((x) => ({ ...x, _search: `${x.name} ${x.tag} ${x.set}` }));
    const p = listPage({
      intro: "Self-made SVG backgrounds (recolor with CSS variables), 3D icons, avatars, phone/computer frames. Click to view large and copy the path. Sets marked “CC BY” or “attribution” require crediting the author when used (see ATTRIBUTION.txt in the folder).",
      filters: [sel("f-set", "All image sets", uniq(items.map((x) => x.set))), sel("f-tag", "All topics", uniq(items.map((x) => x.tag)))],
      items, wrapClass: "grid-img", pageSize: 120,
      match: (x, [s, t]) => (!s || x.set === s) && (!t || x.tag === t),
      render: (x, i) => `<div class="tile" data-i="${i}"><div class="ph"><img loading="lazy" src="${R + esc(x.path)}" alt=""></div><div class="cap">${esc(x.name)}</div></div>`,
    });
    p.onOpen((x) => modal(x.name, `<p class="meta">${esc(x.set)} · ${esc(x.path)}</p><img style="max-width:100%;max-height:60vh" src="${R + esc(x.path)}">
      ${x.variants ? `<div class="grid-img" style="margin-top:10px">${Object.entries(x.variants).map(([k, v]) => `<a class="tile" href="${R + esc(v)}" target="_blank"><div class="ph"><img loading="lazy" src="${R + esc(v)}"></div><div class="cap">${esc(k)}</div></a>`).join("")}</div>` : ""}`,
      [["Copy path", () => copy(x.path)], ["Open folder", () => open(R + x.path.replace(/[^/]+$/, ""))]]));
  },

  async "3D"() {
    const items = (await data("assets3d")).map((x) => ({ ...x, _search: `${x.name} ${x.type} ${x.tags} ${x.src}` }));
    const p = listPage({
      intro: "HDRI lighting, material textures, 3D models (Poly Haven, ambientCG, Kenney — CC0, free to use) and Rive animations (CC BY — credit the author). Use with Three.js / React Three Fiber / model-viewer. Click to open the folder with the files.",
      filters: [sel("f-src", "All sources", uniq(items.map((x) => x.src))), sel("f-type", "All types", uniq(items.map((x) => x.type)))],
      items, wrapClass: "grid-img", pageSize: 120,
      match: (x, [s, t]) => (!s || x.src === s) && (!t || x.type === t),
      render: (x, i) => `<div class="tile" data-i="${i}"><div class="ph">${x.thumb ? `<img loading="lazy" src="${R + esc(x.thumb)}" alt="">` : esc(x.type || "")}</div><div class="cap">${esc(x.name)} <span class="meta">· ${esc(x.src)}</span></div></div>`,
    });
    p.onOpen((x) => (x.page ? open(x.page) : open(R + x.folder + "/")));
  },

  async "Guides"() {
    const docs = await data("docs");
    view.innerHTML = `<div class="intro">Guide files: how to use each source, a checklist for testing a website before sharing the link, and sample prompts for asking an AI to build a page.</div>
      <div class="list">${docs.map((d) => `<div class="item" data-md="${esc(d)}"><b>${esc(d.split("/").slice(-2).join(" / "))}</b><span class="meta">${esc(d)}</span></div>`).join("")}</div>`;
    view.onclick = (e) => { const b = e.target.closest("[data-md]"); if (b) showMd(b.dataset.md); };
  },
};

const nav = $("#tabs");
function go(name) {
  view.onclick = null;
  nav.querySelectorAll("button").forEach((b) => b.classList.toggle("on", b.textContent === name));
  view.innerHTML = '<p class="meta">Loading…</p>';
  history.replaceState(null, "", "#" + encodeURIComponent(name));
  TABS[name]().catch((e) => (view.innerHTML = `<p>Error: ${esc(e.message)}. Open this page with the OPEN_TOOL.command file (it needs a local server).</p>`));
}
for (const name of Object.keys(TABS)) { const b = document.createElement("button"); b.textContent = name; b.onclick = () => go(name); nav.append(b); }
go(decodeURIComponent(location.hash.slice(1)) in TABS ? decodeURIComponent(location.hash.slice(1)) : "Catalog");
